-- StudyMate AI V3 schema: run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text not null default '',college text not null default '',course text not null default 'B.Tech CSE',year int not null default 1 check(year between 1 and 6),semester int not null default 1 check(semester between 1 and 12),study_hours_per_day numeric not null default 3 check(study_hours_per_day>0 and study_hours_per_day<=16),preferred_time text not null default 'Evening',created_at timestamptz not null default now());
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 100),color text not null default '#8b7cf6',priority int not null default 3 check(priority between 1 and 5),progress int not null default 0 check(progress between 0 and 100),created_at timestamptz not null default now());
create unique index if not exists subjects_owner_name_unique on public.subjects(user_id,lower(name));
create table if not exists public.exams(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,subject_name text not null default 'General',title text not null check(char_length(trim(title)) between 1 and 160),exam_date date not null,importance int not null default 4 check(importance between 1 and 5),created_at timestamptz not null default now());
create table if not exists public.study_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,subject_name text not null default 'General',started_at timestamptz not null default now(),ended_at timestamptz,duration_minutes int not null default 0 check(duration_minutes between 0 and 1440),notes text not null default '',created_at timestamptz not null default now(),check(ended_at is null or ended_at>=started_at));
create table if not exists public.study_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject_id uuid references public.subjects(id) on delete set null,subject_name text not null default 'General',title text not null check(char_length(trim(title)) between 1 and 200),task_date date not null,duration_minutes int not null default 45 check(duration_minutes between 5 and 720),completed boolean not null default false,generated boolean not null default false,reason text not null default '',created_at timestamptz not null default now());
create table if not exists public.quiz_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,topic text not null,score int not null check(score>=0),total int not null check(total>0 and score<=total),answers jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create index if not exists exams_owner_date_idx on public.exams(user_id,exam_date);
create index if not exists sessions_owner_date_idx on public.study_sessions(user_id,started_at desc);
create index if not exists tasks_owner_date_idx on public.study_tasks(user_id,task_date);
alter table public.profiles enable row level security;alter table public.subjects enable row level security;alter table public.exams enable row level security;alter table public.study_sessions enable row level security;alter table public.study_tasks enable row level security;alter table public.quiz_attempts enable row level security;
drop policy if exists profile_owner_select on public.profiles;create policy profile_owner_select on public.profiles for select to authenticated using(id=(select auth.uid()));
drop policy if exists profile_owner_insert on public.profiles;create policy profile_owner_insert on public.profiles for insert to authenticated with check(id=(select auth.uid()));
drop policy if exists profile_owner_update on public.profiles;create policy profile_owner_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
do $$ declare t text;begin foreach t in array array['subjects','exams','study_sessions','study_tasks','quiz_attempts'] loop execute format('drop policy if exists %I on public.%I',t||'_owner_access',t);execute format('create policy %I on public.%I for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()))',t||'_owner_access',t);end loop;end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do update set email=excluded.email;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
